css:
&.slide.tpl {
& { padding:96px 120px 90px; display:flex; flex-direction:column; gap:52px; }
header { flex:none; }
header p { color:var(--accent); font:600 20px/1 var(--font-mono,var(--mono)); letter-spacing:.14em; text-transform:uppercase; margin:0 0 16px; }
header h2 { font-size:72px; line-height:1.04; margin:0; text-wrap:balance; }
header div { font-size:30px; line-height:1.38; color:var(--muted); margin-top:20px; max-width:62ch; }
header :empty { display:none; }
ol { flex:1; display:grid; grid-template-columns:max-content minmax(0,1fr); column-gap:52px; row-gap:30px; align-content:center; list-style:none; padding:0; margin:0; }
li { display:contents; }
li b { display:grid; place-items:center; min-width:150px; min-height:118px; padding:0 30px; border-radius:var(--radius); background:var(--surface); border:1.5px solid var(--line); font:600 58px/1 var(--font-display,inherit); color:var(--ink); white-space:nowrap; transition:all .35s ease; }
li span { align-self:center; font-size:29px; line-height:1.4; color:var(--ink); opacity:0; transition:opacity .35s ease; max-width:58ch; }
li span mark { background:none; color:var(--accent); font-weight:650; }
li.in span,li:not([data-step]) span { opacity:1; }
li.step-current b { color:var(--accent); border-color:var(--accent); background:color-mix(in srgb,var(--accent) 12%,var(--surface)); box-shadow:0 0 0 8px var(--hl); }
li.step-past b,li.step-past span { opacity:.5; }
&:has([data-template-end].in),&:has([data-template-end]:not([data-step])) { li b { opacity:1; color:var(--accent); border-color:var(--line); box-shadow:none; background:var(--surface); } li span { opacity:1; } }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }
}
